        try{for(let index=0;index<roles.length;index++){const name=roles[index],box=native('datetime-edit-'+name+'-field');if(!box.width||!box.height)continue;boxes.push({name,box});const text=labels[index];span.textContent=text;const range=document.createRange();range.selectNodeContents(span);const full=range.getBoundingClientRect();assert(near(full.width+2,box.width)&&near(full.height+2,box.height),'empty native reference changed '+input.type+'/'+name+' '+JSON.stringify({full:full.toJSON(),box:box.toJSON()}));for(let offset=0;offset<text.length;offset++){range.setStart(span.firstChild,offset);range.setEnd(span.firstChild,offset+1);const glyph=range.getBoundingClientRect();out.push({input,key:input.type+'/'+name+'/'+offset,offset:index*16+offset,point:point({left:box.left+1+glyph.left-full.left,top:box.top+1,width:glyph.width,height:glyph.height})});}}}finally{span.remove();}
        boxes.sort((a,b)=>a.box.left-b.box.left);for(let i=1;i<boxes.length;i++){const a=boxes[i-1],b=boxes[i];if(b.box.left>a.box.right)out.push({input,key:input.type+'/literal/'+a.name+'/'+b.name,point:point({left:a.box.right,top:literal.top,width:b.box.left-a.box.right,height:literal.height})});}
