await test('原生日期重复状态每次核验真实字段，变化后重新解码且减少重复位探针',()=>{
    const input=document.createElement('input');input.type='time';input.step='0.001';input.style.cssText='position:fixed;left:30px;top:30px;width:380px;font:16px/24px Arial';document.body.append(input);let probes=0,events=0;const create=document.createElement;document.createElement=(name,...args)=>{if(name==='i')probes++;return create.call(document,name,...args);};for(const type of ['input','change'])input.addEventListener(type,()=>events++);
    try{
        input.value='00:00:00.000';const initial=componentDateField(input),first=probes;probes=0;const repeated=componentDateField(input),second=probes;assert(initial&&repeated&&JSON.stringify(initial.text)===JSON.stringify(repeated.text)&&second<first,'native state was not verified/reused');
        input.value='12:34:00.000';const changed=componentDateField(input);assert(changed?.text[3]==='12'&&changed.text[4]==='34','changed native values reused stale state');
        input.value='';const empty=componentDateField(input);assert(empty?.text[3]==='--'&&empty.text[4]==='--'&&empty.text[5]==='--'&&empty.text[6]==='---','empty native fields reused numeric state');
        input.type='date';const date=componentDateField(input);assert(JSON.stringify(date?.text)===JSON.stringify([' 年 ','月','日']),'changed field roles reused time state');
        input.style.font='16px/24px monospace';const mirror=create.call(document,'span');mirror.style.cssText='position:fixed;visibility:hidden;white-space:pre;font:16px/24px monospace';document.body.append(mirror);const width=text=>{mirror.textContent=text;const range=document.createRange();range.selectNodeContents(mirror);return range.getBoundingClientRect().width;};const spacing=(width('0000')-width(' 年 '))/2;mirror.style.wordSpacing=input.style.wordSpacing=spacing+'px';assert(near(width('0000'),width(' 年 ')),'ambiguous native font fixture not ambiguous');mirror.remove();input.focus();const html=input.outerHTML,ambiguous=componentDateField(input);assert(JSON.stringify(ambiguous?.text)===JSON.stringify([' 年 ','月','日'])&&input.outerHTML===html&&document.activeElement===input,'ambiguous placeholder did not calibrate and restore');
        assert(events===0&&!document.querySelector('.collab-text-measure:not(style)'),'state verification changed native events or leaked hosts');document.querySelector('#results').dataset.nativeDateStateReuse=JSON.stringify({first,second,events,changes:3,ambiguousSpacing:spacing});
    }finally{document.createElement=create;input.remove();clearComponentStyles();}
});

